<script setup lang="ts">
import {useSessionStore} from '@/session/store';
import {useReadFeedback} from '@/ui/useReadFeedback';
import {useLocalDraft} from '@/ui/useLocalDraft';
import {ref,onBeforeUnmount} from 'vue';import PageHeading from '@/ui/components/PageHeading.vue';import MessageInput from '@/ui/components/MessageInput.vue';import VoicePlayer from '@/ui/components/VoicePlayer.vue';import ChatImageViewer from '@/ui/components/ChatImageViewer.vue';import {apiRequest,captureApiLease,newIdempotencyKey} from '@/api/client';import {serviceOrigin} from '@/api/runtime';import {userError} from '@/domain/userError.mjs';import {reserveSave,saveVerified} from '@/native/save';import {sha256} from '@noble/hashes/sha2.js';import {bytesToHex} from '@noble/hashes/utils.js';import {chatTime} from '@/chat/time';
const owner=captureApiLease().account,lease={account:owner,valid:()=>{const current=captureApiLease();return current.account===owner&&current.valid();}},text=ref(''),media=ref<Array<{name:string;mime:string;bytes_base64:string;url:string}>>([]),records=ref<any[]>([]),error=ref(''),busy=ref(false),recording=ref(false),picker=ref<HTMLInputElement|null>(null),viewer=ref('');
const preparing=ref(false),requestingPermission=ref(false),finishing=ref(false),listLoading=ref(false);
const {error:listError,feedback:listFeedback}=useReadFeedback({retry:()=>refresh(),ready:()=>useSessionStore().businessReady});
let viewerBlob:Blob|null=null,discardRecording=false;let listGeneration=0;
let recorder:MediaRecorder|null=null,stream:MediaStream|null=null,disposed=false,timer:ReturnType<typeof setTimeout>|undefined,key='',pending:any=null,recordGeneration=0;
const draft=useLocalDraft<{key:string;body:any}>('inspiration_pending',()=>pending||text.value||media.value.length?{key,body:pending||{text:text.value,media:media.value.map(({name,mime,bytes_base64})=>({name,mime,bytes_base64}))}}:null,cached=>{
 if(!cached.body||typeof cached.body.text!=='string'||!Array.isArray(cached.body.media))throw Error('invalid draft');
 pending=cached.key?cached.body:null;key=cached.key||'';text.value=cached.body.text;media.value=cached.body.media.map((a:any)=>({...a,url:'data:'+a.mime+';base64,'+a.bytes_base64}));
});
async function refresh(){const n=++listGeneration;listLoading.value=true;listFeedback.begin(records.value.length>0);try{const r=await apiRequest<{records:any[]}>('GET','/business/v1/inspirations');if(lease.valid()&&!disposed&&n===listGeneration){records.value=r.records;listFeedback.succeeded();}}catch(e){if(lease.valid()&&!disposed&&n===listGeneration){if([401,403].includes((e as any)?.status))records.value=[];listFeedback.failed(e,'灵感记录暂未更新，请重试');}}finally{if(!disposed&&n===listGeneration)listLoading.value=false;}}
void draft.ready.then(()=>{if(!disposed&&lease.valid())void refresh();});
async function referenceImage(file:File){
 if(file.size>16*1024*1024)throw Error('请选择16MB以内的参考图片');
 const source=URL.createObjectURL(file);try{const img=new Image();img.src=source;await img.decode();const ratio=Math.min(1,4096/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');if(!ctx)throw Error('无法处理图片');ctx.drawImage(img,0,0,canvas.width,canvas.height);const preview=canvas.toDataURL('image/jpeg',.92);return {mime:'image/jpeg',bytes_base64:preview.split(',')[1],preview};}finally{URL.revokeObjectURL(source);}
}
function removeMedia(i:number){const a=media.value[i];if(a?.url.startsWith('blob:'))URL.revokeObjectURL(a.url);media.value.splice(i,1);}
async function images(e:Event){const input=e.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(preparing.value||busy.value||pending||recording.value||requestingPermission.value||finishing.value||!draft.readyToEdit.value)return;preparing.value=true;error.value='';try{for(const file of files){if(media.value.length>=5)throw Error('一条灵感最多5个图片或录音');const p=await referenceImage(file);if(!lease.valid()||disposed)return;media.value.push({name:file.name,mime:p.mime,bytes_base64:p.bytes_base64,url:p.preview});}}catch(e){if(!disposed&&lease.valid())error.value=userError(e,'图片未添加，请重试');}finally{if(!disposed)preparing.value=false;}}
function releaseRecording(){stream?.getTracks().forEach(t=>{t.removeEventListener?.('ended',interrupted);t.stop();});stream=null;clearTimeout(timer);recording.value=false;}
function stopRecording(cancel=false){recordGeneration++;requestingPermission.value=false;discardRecording=discardRecording||cancel;recording.value=false;finishing.value=!!recorder&&recorder.state!=='inactive';if(recorder&&recorder.state!=='inactive')recorder.stop();releaseRecording();}
function interrupted(){if(!recording.value)return;error.value='录音中断，请重新录制';stopRecording(true);}
async function voice(){
 if(recording.value){stopRecording();return;}
 if(requestingPermission.value||finishing.value||preparing.value||media.value.length>=5||busy.value||pending||!draft.readyToEdit.value)return;
 if(typeof MediaRecorder==='undefined'||!navigator.mediaDevices?.getUserMedia){error.value='当前设备不支持直接录音';return;}
 error.value='';requestingPermission.value=true;const n=++recordGeneration;
 try{
  const capture=await navigator.mediaDevices.getUserMedia({audio:true});if(disposed||!lease.valid()||n!==recordGeneration){capture.getTracks().forEach(t=>t.stop());return;}
  requestingPermission.value=false;stream=capture;stream.getTracks().forEach(t=>t.addEventListener?.('ended',interrupted));
  const mime=['audio/mp4','audio/webm;codecs=opus','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(capture,mime?{mimeType:mime}:undefined);const source=recorder;
  const chunks:Blob[]=[];let size=0;discardRecording=false;
  source.ondataavailable=e=>{size+=e.data.size;if(size>12*1024*1024){error.value='录音过长，请分段记录';stopRecording(true);}else if(e.data.size)chunks.push(e.data);};
  source.onstop=async()=>{
   if(recording.value){discardRecording=true;error.value='录音中断，请重新录制';}releaseRecording();
   try{if(disposed||!lease.valid()||discardRecording||size>12*1024*1024)return;const blob=new Blob(chunks,{type:source.mimeType||'audio/webm'});if(!blob.size){error.value='没有录到声音，请重试';return;}
    const bytes=new Uint8Array(await blob.arrayBuffer());if(disposed||!lease.valid()||discardRecording)return;let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));media.value.push({name:'灵感录音',mime:blob.type,bytes_base64:btoa(binary),url:URL.createObjectURL(blob)});
   }finally{finishing.value=false;}
  };
  source.onerror=()=>{error.value='录音中断，请重试';stopRecording(true);};source.start(1000);recording.value=true;timer=setTimeout(()=>stopRecording(),120000);
 }catch(e){if(disposed||!lease.valid()||n!==recordGeneration)return;releaseRecording();error.value=userError(e,'无法录音，请检查麦克风权限');}
 finally{if(n===recordGeneration)requestingPermission.value=false;}
}
async function save(){if(busy.value||recording.value||requestingPermission.value||finishing.value||preparing.value||!draft.readyToEdit.value||!lease.valid()||(!text.value.trim()&&!media.value.length&&!pending))return;busy.value=true;error.value='';if(!pending){key=newIdempotencyKey('inspiration');pending={text:text.value,media:media.value.map(({name,mime,bytes_base64})=>({name,mime,bytes_base64}))};}let attempted=false;try{await draft.flush();if(!lease.valid()||disposed)return;attempted=true;await apiRequest('POST','/business/v1/inspirations',{body:pending,idempotencyKey:key});if(!lease.valid()||disposed)return;pending=null;key='';text.value='';for(const a of media.value)if(a.url.startsWith('blob:'))URL.revokeObjectURL(a.url);media.value=[];await draft.flush();await refresh();}catch(e){if(!attempted||[400,413,415,422].includes((e as any)?.status)){pending=null;key='';await draft.flush().catch(()=>{});}if(!disposed&&lease.valid())error.value=userError(e,'保存未确认，请用原内容重试');}finally{busy.value=false;}}
async function openImage(a:any){try{const r=await fetch(serviceOrigin()+'/business/v1/inspirations/'+encodeURIComponent(a.id)+'/media',{credentials:'include',cache:'no-store'});if(!r.ok)throw Error('图片暂时无法读取');const blob=await r.blob();if(!lease.valid()||disposed)return;closeImage();viewerBlob=blob;viewer.value=URL.createObjectURL(blob);}catch(e){error.value=userError(e);}}
function closeImage(){if(viewer.value.startsWith('blob:'))URL.revokeObjectURL(viewer.value);viewer.value='';viewerBlob=null;}
async function saveImage(){if(!viewerBlob||!lease.valid())return;const blob=viewerBlob;let target;try{target=await reserveSave('灵感参考图片.jpg');if(!lease.valid()){target?.cancel();return;}const hash=bytesToHex(sha256(new Uint8Array(await blob.arrayBuffer())));await saveVerified(blob,'灵感参考图片.jpg',hash,[lease.account,'inspiration',hash],lease.valid,target);}catch(e){target?.cancel();error.value=userError(e,'图片未保存，请重试');}}
onBeforeUnmount(()=>{disposed=true;listGeneration++;stopRecording(true);closeImage();for(const a of media.value)if(a.url.startsWith('blob:'))URL.revokeObjectURL(a.url);});
</script>
<template><div class="inspiration-page"><PageHeading title="个人灵感记录"/><p v-if="draft.restoring.value" role="status" class="field-help">正在恢复草稿…</p><MessageInput v-model="text" aria-label="灵感内容" placeholder="记录灵感…" :disabled="busy||!!pending||!draft.readyToEdit.value" maxlength="10000"/><div class="capture-actions"><button class="btn" :disabled="busy||!!pending||requestingPermission||preparing||finishing||!draft.readyToEdit.value" @click="voice">{{requestingPermission?'正在打开麦克风…':recording?'结束录音':'语音记录'}}</button><button class="btn" :disabled="busy||!!pending||recording||requestingPermission||preparing||finishing||!draft.readyToEdit.value" @click="picker?.click()">添加图片</button><button class="btn primary" :disabled="busy||recording||requestingPermission||finishing||preparing||!draft.readyToEdit.value||(!pending&&!text.trim()&&!media.length)" @click="save">{{busy?'正在保存…':pending?'重试保存':'保存'}}</button></div><button v-if="recording||requestingPermission" class="btn" @click="stopRecording(true)">取消录音</button><input ref="picker" hidden type="file" accept="image/*" multiple @change="images"/><div class="capture-media"><div v-for="(a,i) in media" :key="a.url"><img v-if="a.mime.startsWith('image/')" :src="a.url" alt="参考图片"/><VoicePlayer v-else :src="a.url"/><button class="btn small" :disabled="busy||!!pending||!draft.readyToEdit.value" @click="removeMedia(i)">移除</button></div></div><p v-if="error" role="alert" class="field-help">{{error}}</p><p v-if="draft.error.value" role="alert" class="field-help">{{draft.error.value}}<button class="btn small" @click="draft.retry().catch(()=>{})">重试保留草稿</button></p><p v-if="listError" role="alert" class="field-help">{{listError}}<button class="btn small" :disabled="listLoading" @click="refresh">重试读取</button></p><p v-else-if="listLoading" role="status">正在读取灵感…</p><p v-else-if="!records.length" class="field-help">暂无灵感记录</p><article v-for="r in records" :key="r.id" class="inspiration-record"><time>{{chatTime(r.created_at)}}</time><p>{{r.body}}</p><div class="record-media"><template v-for="a in r.media" :key="a.id"><button v-if="a.mime.startsWith('image/')" class="btn small" @click="openImage(a)">查看参考图片</button><VoicePlayer v-else :src="serviceOrigin()+'/business/v1/inspirations/'+encodeURIComponent(a.id)+'/media'" label="灵感录音"/></template></div></article><Teleport to="body"><ChatImageViewer v-if="viewer" :url="viewer" name="灵感参考图片" @close="closeImage" @save="saveImage" @actions="saveImage"/></Teleport></div></template>
<style scoped>.inspiration-page{padding:12px}.inspiration-intro{font-size:14px;color:var(--muted);margin:14px 0}.inspiration-page>.message-input{width:100%;height:100px;min-height:100px}.capture-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.capture-actions>.primary{margin-left:auto}.capture-media{display:grid;gap:12px}.capture-media img{width:100px;height:100px;object-fit:contain}.capture-media>div{display:flex;align-items:center;gap:8px}.inspiration-record{border-top:1px solid var(--line);padding:14px 0}.inspiration-record time{font-size:11px;color:var(--muted)}.inspiration-record p{overflow-wrap:anywhere;font-size:15px;line-height:1.6;white-space:pre-wrap;margin:8px 0}.record-media{display:grid;gap:8px}</style>
